changeSet.sql:
CREATE TABLE user_account ( id UUID PRIMARY KEY, email VARCHAR(320) NOT NULL, phone_number VARCHAR(32) NULL, password_hash VARCHAR(255) NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL, last_login_at TIMESTAMP NULL, CONSTRAINT uk_user_account_email UNIQUE (email), CONSTRAINT uk_user_account_phone_number UNIQUE (phone_number) );
CREATE TABLE role ( id UUID PRIMARY KEY, code VARCHAR(80) NOT NULL, name VARCHAR(160) NOT NULL, CONSTRAINT uk_role_code UNIQUE (code) );
CREATE TABLE permission ( id UUID PRIMARY KEY, code VARCHAR(120) NOT NULL, description VARCHAR(255) NULL, CONSTRAINT uk_permission_code UNIQUE (code) );
CREATE TABLE user_role ( user_id UUID NOT NULL, role_id UUID NOT NULL, CONSTRAINT pk_user_role PRIMARY KEY (user_id, role_id), CONSTRAINT fk_user_role_user FOREIGN KEY (user_id) REFERENCES user_account(id), CONSTRAINT fk_user_role_role FOREIGN KEY (role_id) REFERENCES role(id) );
CREATE TABLE refresh_token ( id UUID PRIMARY KEY, user_id UUID NOT NULL, token_hash VARCHAR(255) NOT NULL, family_id UUID NOT NULL, issued_at TIMESTAMP NOT NULL, expires_at TIMESTAMP NOT NULL, revoked_at TIMESTAMP NULL, replaced_by_token_id UUID NULL, ip_address VARCHAR(80) NULL, user_agent TEXT NULL, CONSTRAINT fk_refresh_token_user FOREIGN KEY (user_id) REFERENCES user_account(id), CONSTRAINT uk_refresh_token_hash UNIQUE (token_hash) );
CREATE INDEX idx_refresh_token_family ON refresh_token(family_id); CREATE INDEX idx_refresh_token_user ON refresh_token(user_id);

CREATE TABLE IF NOT EXISTS role_permission ( role_id UUID NOT NULL, permission_id UUID NOT NULL, CONSTRAINT pk_role_permission PRIMARY KEY (role_id, permission_id), CONSTRAINT fk_role_permission_role FOREIGN KEY (role_id) REFERENCES role(id), CONSTRAINT fk_role_permission_permission FOREIGN KEY (permission_id) REFERENCES permission(id) );
CREATE TABLE IF NOT EXISTS password_reset_token ( id UUID PRIMARY KEY, user_id UUID NOT NULL, token_hash VARCHAR(255) NOT NULL, issued_at TIMESTAMP NOT NULL, expires_at TIMESTAMP NOT NULL, used_at TIMESTAMP NULL, CONSTRAINT fk_password_reset_token_user FOREIGN KEY (user_id) REFERENCES user_account(id), CONSTRAINT uk_password_reset_token_hash UNIQUE (token_hash) );
CREATE INDEX IF NOT EXISTS idx_password_reset_token_user ON password_reset_token(user_id);
INSERT INTO permission (id, code, description) VALUES ('00000000-0000-0000-0000-000000001001', 'IAM_USER_READ', 'Read IAM users'), ('00000000-0000-0000-0000-000000001002', 'IAM_USER_STATUS_WRITE', 'Change IAM user status'), ('00000000-0000-0000-0000-000000001003', 'IAM_ROLE_ASSIGN', 'Assign and remove IAM roles'), ('00000000-0000-0000-0000-000000001004', 'IAM_PASSWORD_CHANGE', 'Change own password'), ('00000000-0000-0000-0000-000000001005', 'POLICY_READ', 'Read policy data'), ('00000000-0000-0000-0000-000000001006', 'CLAIM_CREATE', 'Create claim'), ('00000000-0000-0000-0000-000000001007', 'CLAIM_REVIEW', 'Review claim'), ('00000000-0000-0000-0000-000000001008', 'HEALTH_RECORD_READ', 'Read health records'), ('00000000-0000-0000-0000-000000001009', 'HEALTH_RECORD_WRITE', 'Write health records') ON CONFLICT (code) DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT role.id, permission.id FROM role JOIN permission ON permission.code IN ( 'IAM_USER_READ', 'IAM_USER_STATUS_WRITE', 'IAM_ROLE_ASSIGN', 'IAM_PASSWORD_CHANGE', 'POLICY_READ', 'CLAIM_CREATE', 'CLAIM_REVIEW', 'HEALTH_RECORD_READ', 'HEALTH_RECORD_WRITE' ) WHERE role.code = 'ADMIN' ON CONFLICT DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT role.id, permission.id FROM role JOIN permission ON permission.code IN ('IAM_PASSWORD_CHANGE', 'POLICY_READ', 'CLAIM_CREATE', 'HEALTH_RECORD_READ') WHERE role.code = 'PATIENT' ON CONFLICT DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT role.id, permission.id FROM role JOIN permission ON permission.code IN ('IAM_PASSWORD_CHANGE', 'HEALTH_RECORD_READ', 'HEALTH_RECORD_WRITE') WHERE role.code = 'DOCTOR' ON CONFLICT DO NOTHING;
INSERT INTO role_permission (role_id, permission_id) SELECT role.id, permission.id FROM role JOIN permission ON permission.code IN ('IAM_PASSWORD_CHANGE', 'POLICY_READ', 'CLAIM_REVIEW') WHERE role.code = 'AGENT' ON CONFLICT DO NOTHING;

rollback.sql:
DROP TABLE IF EXISTS password_reset_token;
DROP TABLE IF EXISTS role_permission;
DELETE FROM permission WHERE code IN (
    'IAM_USER_READ',
    'IAM_USER_STATUS_WRITE',
    'IAM_ROLE_ASSIGN',
    'IAM_PASSWORD_CHANGE',
    'POLICY_READ',
    'CLAIM_CREATE',
    'CLAIM_REVIEW',
    'HEALTH_RECORD_READ',
    'HEALTH_RECORD_WRITE'
);

